                "حَسَدَهُ إِخْوَتُهُ وَأَلْقَوْهُ فِي البِئْرِ وَجَاؤُوا بِقَمِيصِهِ السَّلِيمِ وَمَعَهُمْ ذِئْبٌ لِيَخْدَعُوا أَبَاهُمْ، فَفَحَصَ يَعْقُوبُ القَمِيصَ بِعَقْلِهِ وَدَعَا اللهَ فَأَنْطَقَ الذِّئْبَ بِبَرَاءَتِهْ، فَقَالَ يَعْقُوبُ لِبَنِيهِ: بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَاللهُ المُسْتَعَانْ.",
