                "آمَنَ مَعَهُ الفُقَرَاءُ وَأَصْحَابُ الحِرَفِ المُتَوَاضِعُونَ بَيْنَمَا تَكَبَّرَ الأَغْنِيَاءُ وَكَانُوا يَضْرِبُونَهْ، فَإِذَا أَفَاقَ عَادَ يُنَحِّي عَنْهُمْ طَرِيقَ البَاطِلِ تِسْعَمِائَةٍ وَخَمْسِينَ سَنَةً بِصَبْرٍ جَمِيلْ، ثُمَّ أَمَرَهُ اللهُ أَنْ يَغْرِسَ الأَشْجَارَ ثُمَّ قَطَعَهَا وَنَحَّى عَنْهَا القُشُورَ لِيَبْنِيَ سَفِينَةَ النَّجَاةِ فِي سَاحَةٍ وَاسِعَةٍ مِنْ ذَوَاتِ الدُّسُرِ وَالأَلْوَاحْ.",
                "وَلَمَّا فَارَ التَّنُّورُ بِالمَاءِ أَدْخَلَ نُوحٌ فِي السَّفِينَةِ مِنْ كُلٍّ زَوْجَيْنِ اثْنَيْنِ وَالأَزْوَاجَ الثَّمَانِيَةَ مِنَ الأَنْعَامِ وَمِنْ كُلِّ حُبُوبٍ نَافِعَةْ، وَصَعِدَ مَعَهُ أَبْنَاؤُهُ الثَّلَاثَةُ وَثَمَانُونَ مِنَ المُؤْمِنِينَ وَقَالَ لَهُمُ: ارْكَبُوا فِيهَا بِسْمِ اللهِ مَجْرَاهَا وَمُرْسَاهَا إِنَّ رَبِّي لَغَفُورٌ رَحِيمْ.",
                "فَتَحَ اللهُ أَبْوَابَ السَّمَاءِ وَفَجَّرَ الأَرْضَ عُيُونًا فَاغْتَمَرَتِ الأَرْضُ بِمِيَاهِ بُحُورٍ عَمِيقَةْ، فَهَلَكَتِ امْرَأَةُ نُوحٍ الخَائِنَةُ وَابْنُهُ كَنْعَانُ الَّذِي رَفَضَ الرُّكُوبَ مَعَ المُؤْمِنِينْ، ثُمَّ أَمَرَ اللهُ الأَرْضَ فَبَلَعَتْ مَاءَهَا وَاسْتَوَتِ السَّفِينَةُ عَلَى جَبَلِ الجُودِيِّ بِسَلَامْ.",
