                "ذَهَبَ مُوسَى وَهَارُونُ إِلَى فِرْعَوْنَ فَأَبْطَلَتِ العَصَا سِحْرَ السَّحَرَةِ حَتَّى آمَنُوا وَخَرُّوا سُجَّدًا للهِ، وَأَرْسَلَ اللهُ عَلَى فِرْعَوْنَ وَقَوْمِهِ تِسْعَ آيَاتٍ بَيِّنَاتٍ وَنَقْصًا مِنَ الثَّمَرَاتِ فَاسْتَكْبَرُوا، ثُمَّ سَارَ مُوسَى بِبَنِي إِسْرَائِيلَ لَيْلًا فَلَحِقَهُمْ فِرْعَوْنُ، فَقَالَ مُوسَى بِيَقِينٍ: كَلَّا إِنَّ مَعِيَ رَبِّي سَيَهْدِينْ! وَضَرَبَ البَحْرَ بِعَصَاهُ فَانْفَلَقَ اثْنَيْ عَشَرَ طَرِيقًا فَعَبَرَ المُؤْمِنُونَ وَغَمَرَ اليَمُّ فِرْعَوْنَ وَجُنُودَهْ.",
                "أَنْزَلَ اللهُ عَلَيْهِمُ المَنَّ وَالسَّلْوَى طَعَامًا طَيِّبًا، وَضَرَبَ مُوسَى الحَجَرَ بِعَصَاهُ فَانْفَجَرَتْ مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا مِنْ مَاءٍ عَذْبْ، وَذَهَبَ إِلَى مِيقَاتِ رَبِّهِ أَرْبَعِينَ لَيْلَةً عِنْدَ الطُّورِ فَكَتَبَ اللهُ لَهُ التَّوْرَاةَ وَأَتَمَّ لَهُ النُّورَ، وَكَانَ اللهُ يُكَلِّمُ مُوسَى تَكْلِيمًا فَهُوَ نَبِيٌّ كَلِيمٌ كَرِيمْ.",
