                "وَعَلَّمَهُ اللهُ مَنْطِقَ الطَّيْرِ وَالحَيَوَانْ، وَفِي يَوْمٍ حُشِرَ لَهُ جُنُودُهُ مِنَ الجِنِّ وَالإِنْسِ وَالطَّيْرِ حَتَّى أَتَوْا عَلَى وَادِي النَّمْلْ، فَخَافَتْ نَمْلَةٌ حَكِيمَةٌ فَنَادَتْ قَوْمَهَا لِيَدْخُلُوا مَسَاكِنَهُمْ، فَسَمِعَ سُلَيْمَانُ كَلَامَهَا فَتَبَسَّمَ وَأَوْقَفَ الجَيْشَ حَتَّى آمِنَ النَّمْلُ وَشَكَرَ كُلَّ نِعْمَةٍ وَهَبَهَا اللهُ لَهْ.",
                "تَفَقَّدَ سُلَيْمَانُ الطَّيْرَ فَجَاءَ الهُدْهُدُ فَنَطَقَ بِخَبَرٍ صَادِقٍ مِنْ سَبَأٍ عَنْ مَلِكَتِهِمْ بِلْقِيسَ وَقَوْمِهَا الَّذِينَ سَجَدُوا لِلشَّمْسِ مِنْ دُونِ اللهْ، فَأَرْسَلَ سُلَيْمَانُ كِتَابًا يَبْدَأُ بـ: إِنَّهُ مِنْ سُلَيْمَانَ وَإِنَّهُ بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيمِ أَلَّا تَعْلُوا عَلَيَّ وَأْتُونِي مُسْلِمِينْ.",
                "أَحْضَرَ وَصِيُّهُ آصِفُ بْنُ بَرْخِيَا عَرْشَ بِلْقِيسَ قَبْلَ أَنْ يَرْتَدَّ إِلَيْهِ طَرْفُهُ، فَلَمَّا رَأَتْهُ وَدَخَلَتِ الصَّرْحَ المُمَرَّدَ مِنْ قَوَارِيرَ أَسْلَمَتْ مَعَ سُلَيْمَانَ للهِ رَبِّ العَالَمِينْ، وَحِينَ عُرِضَتْ عَلَيْهِ الصَّافِنَاتُ الجِيَادُ رَدَّ اللهُ لَهُ الشَّمْسَ حَتَّى صَلَّى العَصْرَ فِي وَقْتِهَا وَكَانَ يَرْجِعُ إِلَى رَبِّهِ كَمَا قَالَ تَعَالَى: ثُمَّ أَنَابَ.",
