                "لٰكِنَّ أَشْقَى القَوْمِ قُدَارَ بْنَ سَالِفٍ عَقَرَ النَّاقَةَ وَرَضِيَ القَوْمُ بِفِعْلِهِ، فَهَرَبَ فَصِيلُهَا إِلَى الجَبَلِ وَرَغَا ثَلَاثَ رَغَوَاتْ، فَأَنْذَرَهُمْ صَالِحٌ بِالعَذَابِ بَعْدَ ثَلَاثَةِ أَيَّامٍ وَأَهْلَكَ اللهُ التِّسْعَةَ المُفْسِدِينَ الَّذِينَ تَآمَرُوا عَلَى قَتْلِ نَبِيِّهْ.",
