                "كَانَ ذُو الكِفْلِ يَصُومُ النَّهَارَ وَيَقُومُ اللَّيْلَ يُصَلِّي وَيَذْكُرُ رَبَّهُ وَلَا يَنَامُ إِلَّا سَاعَةً وَاحِدَةً عِنْدَ القَيْلُولَةِ فِي الظَّهِيرَةْ، فَأَرَادَ الشَّيْطَانُ أَنْ يُوقِعَهُ فِي الغَضَبِ فَذَهَبَ فِي صُورَةِ شَيْخٍ وَطَرَقَ بَابَهُ وَقْتَ نَوْمِهِ فَذَكَرَ لَهُ أَنَّ قَوْمَهُ ظَلَمُوهْ! فَفَتَحَ لَهُ بِحِلْمٍ وَدَعَاهُ إِلَى مَجْلِسِ القَضَاءِ فَلَمْ يَأْتِ الشَّيْخُ.",
                "وَفِي اليَوْمِ الثَّانِي عَادَ وَقْتَ القَيْلُولَةِ يَدُقُّ البَابَ، فَلَمْ يَغْضَبْ نَبِيُّ اللهِ وَقَالَ لَهُ: خُذْ هٰذَا الخَاتَمَ وَائْتِ بِهِ قَوْمَكَ لِيَحْضُرُوا مَعَكَ، فَأَخَذَ الشَّيْخُ الخَاتَمَ وَمَضَى وَلَمْ يَحْضُرْ وَضَاعَتْ قَيْلُولَةُ نَبِيِّ اللهِ لِليَوْمِ الثَّانِي.",
                "وَفِي اليَوْمِ الثَّالِثِ مَنَعَهُ الحُرَّاسُ فَنَزَلَ مِنْ كُوَّةِ السَّقْفِ وَأَيْقَظَ نَبِيَّ اللهِ، فَنَظَرَ ذُو الكِفْلِ إِلَى البَابِ المُقْفَلِ فَعَرَفَ أَنَّهُ الشَّيْطَانُ الَّذِي أَرَادَ أَنْ يُغْضِبَهُ فَعَجَزَ عَنْهُ! فَلَمْ يَغْضَبْ ذُو الكِفْلِ بَلِ اسْتَعَاذَ بِاللهِ وَكَذَّبَ وَسْوَسَتَهُ كَمَا يُكَذِّبُ المُؤْمِنُ البَاطِلَ لِيَنْجُوَ مِنْ عَذَابِ السَّعِيرْ.",
